'use strict';

/**
* Compute the inertia between double-precision floating-point centroids and data points.
*
* @module @stdlib/ml/strided/dkmeans-compute-inertia
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
* var dcomputeInertia = require( '@stdlib/ml/strided/dkmeans-compute-inertia' );
*
* var X = new Float64Array( [ 1.0, 1.0, 5.0, 5.0, 1.5, 1.5 ] );
* var C = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
* var labels = new Int32Array( [ 0, 1, 0 ] );
*
* var inertia = dcomputeInertia( 'row-major', 3, 2, 2, 'sqeuclidean', X, 2, C, 2, labels, 1 );
* // returns 0.5
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
* var dcomputeInertia = require( '@stdlib/ml/strided/dkmeans-compute-inertia' );
*
* var X = new Float64Array( [ 1.0, 1.0, 5.0, 5.0, 1.5, 1.5 ] );
* var C = new Float64Array( [ 1.0, 1.0, 5.0, 5.0 ] );
* var labels = new Int32Array( [ 0, 1, 0 ] );
*
* var inertia = dcomputeInertia.ndarray( 3, 2, 2, 'sqeuclidean', X, 2, 1, 0, C, 2, 1, 0, labels, 1, 0 );
* // returns 0.5
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dcomputeInertia;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dcomputeInertia = main;
} else {
	dcomputeInertia = tmp;
}


// EXPORTS //

module.exports = dcomputeInertia;

// exports: { "ndarray": "dcomputeInertia.ndarray" }
